mapper.select:
SELECT coupon_id AS couponId, user_id AS userId, coupon_name AS couponName, coupon_amount AS couponAmount, expire_time AS expireTime, status, order_id AS orderId, use_time AS useTime, coupon_type AS couponType, min_order_amount AS minOrderAmount, create_time AS createTime, update_time AS updateTime FROM user_coupons
AND coupon_id = #{couponId}
AND user_id = #{userId}
AND status = #{status}
ORDER BY create_time DESC
